  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Tetrabenazine, a structurally related benzoquinolizine alkaloid, showed oral bioavailability of 0.005 in a patient after chronic oral dosing, indicating very low systemic availability.",
