      "card_ids": ["C22"],
      "claim": "Almorexant had an absolute oral bioavailability of 11.2% (90% CI 9.6–13.1) in healthy subjects, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Terameprocol had an absolute oral bioavailability of approximately 2% in patients, far below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Trospium chloride achieved only 3–11% oral bioavailability in humans due to slow gastrointestinal absorption, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Physostigmine, an acetylcholinesterase inhibitor like the query, has poor oral bioavailability, supporting a low-F prediction for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Thienorphine (ThH) had very low oral bioavailability in humans, restricting its development, consistent with a low-F outcome.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
